import AppKit

struct SamplePlaybackSettings:Codable,Equatable {
    var mode=0,start=0,end=0,slices:[Int]=[],position=500,grainLength=120,shape=2,direction=0,spread=8;var positionAutomation:PositionAutomation?;var octave:Int?
    func normalized(_ frames:Int)->SamplePlaybackSettings{var p=self;let n=max(1,frames);p.mode=max(0,min(5,p.mode));p.start=max(0,min(n-1,p.start));p.end=max(p.start+1,min(n,p.end==0 ? n:p.end));p.slices=Array(Array(Set(p.slices.filter{$0>=p.start&&$0<p.end})).sorted().prefix(48));if p.mode==4{if !p.slices.contains(p.start){p.slices.insert(p.start,at:0)};p.slices=Array(p.slices.prefix(48))};p.position=max(0,min(1000,p.position));p.grainLength=max(1,min(1000,p.grainLength));p.shape=max(0,min(3,p.shape));p.direction=max(0,min(2,p.direction));p.spread=max(0,min(100,p.spread));if let o=p.octave{p.octave=max(-3,min(3,o))};if let a=p.positionAutomation{p.positionAutomation=a.normalized};return p}
}
let playbackModes=["1-Shot","Forward Loop","Backward Loop","Pingpong Loop","Slice","Granular"]
let sampleEffects=["Crop","Reverse","Bitcrusher","Chop Even","Chop Transients","Time Stretch"]
let grainShapes=["Square","Triangle","Gauss","Hann"]
let grainDirections=["Forward","Backward","Pingpong"]

enum SampleEditing {
    static func floats(_ data:Data)->[Float]{var pcm=[Float](repeating:0,count:data.count/4);_ = pcm.withUnsafeMutableBytes{data.copyBytes(to:$0)};return pcm}
    static func bytes(_ p:[Float])->Data{p.withUnsafeBytes{Data($0)}}
    static func evenly(_ start:Int,_ end:Int,_ count:Int)->[Int]{let n=max(1,min(48,min(count,end-start)));return (0..<n).map{start+($0*(end-start))/n}}
    static func transients(_ pcm:[Float],_ start:Int,_ end:Int,_ count:Int,_ rate:Double)->[Int]{let n=max(1,min(48,min(count,end-start)));if n==1{return [start]};let hop=max(1,Int(rate*0.008)),spacing=max(1,(end-start)/(n*3));var candidates=[(Int,Float)](),prev:Float=0;for i in stride(from:start,to:end,by:hop){let e=min(end,i+hop);var energy:Float=0;for j in i..<e{energy+=abs(pcm[j])};energy/=Float(max(1,e-i));let onset=max(0,energy-prev);if i>start{candidates.append((i,onset))};prev=energy};candidates.sort{$0.1>$1.1};var points=[start];for (i,score) in candidates where score>0.001&&points.count<n{if i<end&&points.allSatisfy({abs($0-i)>=spacing}){points.append(i)}};for i in evenly(start,end,n) where points.count<n{if !points.contains(i){points.append(i)}};return points.sorted()}
    static func crush(_ pcm:inout [Float],start:Int,end:Int,bits:Int,hold:Int){let levels=Float(1<<max(1,min(15,bits-1))),stride=max(1,min(32,hold));var value:Float=0;for i in start..<end{if (i-start)%stride==0{value=(pcm[i]*levels).rounded()/levels};pcm[i]=max(-1,min(1,value))}}
}

extension Tracker {
    func stretchSelectedRegion(){guard let data=samplerSlot.pcm,samplerFrames>0 else{return};let p=sampleSettings,oldCount=p.end-p.start,newCount=max(1,Int((Double(oldCount)*Double(sampleStretch)/100).rounded())),total=samplerFrames-oldCount+newCount;guard total<=1_000_000,slots.reduce(0,{$0+($1.pcm?.count ?? 0)})-data.count+total*4<=64_000_000 else{message="Stretch exceeds sample memory limit";return};if sampleStretch==100{message="Length unchanged (100%)";return};var pcm=SampleEditing.floats(data);do{var result=try TimeStretch.render(Array(pcm[p.start..<p.end]),rate:samplerRate,percent:sampleStretch);let fade=min(result.count/2,Int(samplerRate*0.003));if fade>0{for i in 0..<fade{let f=Float(i)/Float(fade);if p.start>0{result[i]=result[i]*f+pcm[p.start+min(oldCount-1,i)]*(1-f)};if p.end<pcm.count{let j=result.count-1-i;result[j]=result[j]*f+pcm[p.end-1-min(oldCount-1,i)]*(1-f)}}};pcm.replaceSubrange(p.start..<p.end,with:result);var next=p;next.end=p.start+result.count;next.slices=p.slices.map{p.start+Int((Double($0-p.start)*Double(result.count)/Double(oldCount)).rounded())};checkpoint();var sl=slots;sl[instrumentRow].pcm=SampleEditing.bytes(pcm);sl[instrumentRow].playback=next.normalized(pcm.count);project.slots=sl;waveCache=nil;sampleCursor=p.start;sampleZoom=1;tm_preview_stop();syncInstruments();message="Time stretch applied: \(sampleStretch)% (R3, pitch unchanged)";sampleStretch=100;needsDisplay=true}catch{message=error.localizedDescription;needsDisplay=true}}
    var samplePage:Bool{page==8||page==9}
    var samplerSlot:InstrumentSlot{slots[instrumentRow]}
    var samplerFrames:Int{(samplerSlot.pcm?.count ?? 0)/4}
    var samplerRate:Double{samplerSlot.sampleRate ?? 48000}
    var sampleSettings:SamplePlaybackSettings{(samplerSlot.playback ?? SamplePlaybackSettings()).normalized(samplerFrames)}
    func selectSamplePage(_ previous:Int){sampleFocus=0;sampleZoom=1;sampleCursor=0;if previous != 7&&previous != 8&&previous != 9&&previous != 10{let i=cell.instrument ?? trackDefaults[track];if i>=0{instrumentRow=i}};if samplerFrames==0,let i=slots.firstIndex(where:{$0.pcm != nil}){instrumentRow=i};sampleCursor=sampleSettings.start;waveCache=nil;needsDisplay=true}
    func setSampleSettings(_ settings:SamplePlaybackSettings,remember:Bool=true){guard samplerFrames>0 else{return};let p=settings.normalized(samplerFrames);if p==sampleSettings{return};if remember{checkpoint()};var sl=slots;sl[instrumentRow].playback=p;project.slots=sl;dirty=true;syncInstruments();needsDisplay=true}
    func moveSampleSlot(_ d:Int){let ids=slots.indices.filter{slots[$0].pcm != nil};guard !ids.isEmpty else{message="Import a sample with 8 — Sample Loader";return};let idx=ids.firstIndex(of:instrumentRow) ?? 0;instrumentRow=ids[max(0,min(ids.count-1,idx+d))];sampleCursor=sampleSettings.start;sampleZoom=1;waveCache=nil;tm_preview_stop();needsDisplay=true}
