    func sampleChop(_ transient:Bool){guard let data=samplerSlot.pcm,samplerFrames>0 else{return};var p=sampleSettings;p.slices=transient ? SampleEditing.transients(SampleEditing.floats(data),p.start,p.end,sampleChops,samplerRate):SampleEditing.evenly(p.start,p.end,sampleChops);p.mode=4;setSampleSettings(p);sampleCursor=p.start;message="\(p.slices.count) slices · C1 = Slice 1"}
