    func changeSampleParameter(_ delta:Int){guard samplerFrames>0 else{if sampleFocus==5{moveSampleSlot(delta>0 ? 1:-1)};return};let sign=delta>0 ? 1:-1;var p=sampleSettings;let frames=max(1,Int(samplerRate*0.010/Double(sampleZoom)))*delta
