        if page==9{switch sampleFocus{case 0:p.start=max(0,min(p.end-1,p.start+frames));case 1:p.end=max(p.start+1,min(samplerFrames,p.end+frames));case 2:sampleZoom=max(1,min(32,sampleZoom+delta));needsDisplay=true;return;case 3:sampleEffect=(sampleEffect+sign+sampleEffects.count)%sampleEffects.count;return;case 4:if sampleEffect==5{sampleStretch=max(50,min(200,sampleStretch+delta));needsDisplay=true;return};if sampleEffect==2{sampleBits=max(2,min(16,sampleBits+sign))}else{sampleChops=max(2,min(48,sampleChops+delta))};return;case 6:sampleHold=max(1,min(32,sampleHold+delta));return;default:break};setSampleSettings(p);return}
        if p.mode==5{switch sampleFocus{case 0:p.position=max(0,min(1000,p.position+delta*5));case 1:p.grainLength=max(1,min(1000,p.grainLength+delta*5));case 2:p.shape=(p.shape+sign+grainShapes.count)%grainShapes.count;case 3:p.direction=(p.direction+sign+grainDirections.count)%grainDirections.count;case 4:p.spread=max(0,min(100,p.spread+delta));default:break};setSampleSettings(p)}else if p.mode==4{if sampleFocus==0{sampleCursor=max(p.start,min(p.end-1,sampleCursor+frames))}else if sampleFocus==1{sampleChops=max(2,min(48,sampleChops+delta))}else if sampleFocus==2{sampleZoom=max(1,min(32,sampleZoom+delta))};needsDisplay=true}else{switch sampleFocus{case 0:p.start=max(0,min(p.end-1,p.start+frames));case 1:p.end=max(p.start+1,min(samplerFrames,p.end+frames));case 2:sampleZoom=max(1,min(32,sampleZoom+delta));return;default:break};setSampleSettings(p)}
    }
    func sampleSoftLabels()->[String]{let preview=tm_preview_active()>0 ? "Stop":"Preview";if page==9{return [preview,"Apply","Undo","Start","End","Zoom","Effect ▲","Effect ▼"]};let p=sampleSettings;if p.mode==5{return [preview,"Position","Length","Shape","Direction","Spread","Mode ▲","Mode ▼"]};if p.mode==4{return [preview,"Cursor","Count","Add","Remove","Auto Chop","Mode ▲","Mode ▼"]};return [preview,"Start","End","Zoom","Octave","","Mode ▲","Mode ▼"]}
    func sampleFooterFocused(_ i:Int)->Bool{if page==9{return sampleFocus<=2 && i==sampleFocus+3};if sampleSettings.mode==4{return sampleFocus<=1&&i==sampleFocus+1};if sampleFocus==7&&sampleSettings.mode != 5{return i==4};return sampleFocus<=4&&i==sampleFocus+1}
    func sampleSoftValues()->[String]{let p=sampleSettings,rate=samplerRate;func seconds(_ frame:Int)->String{String(format:"%.3fs",Double(frame)/rate)};if page==9{return ["",sampleEffects[sampleEffect],"",seconds(p.start),seconds(p.end),"\(sampleZoom)x","",""]};if p.mode==5{return ["",seconds(p.start+Int(Double(p.end-p.start)*Double(p.position)/1000)),"\(p.grainLength) ms",grainShapes[p.shape],grainDirections[p.direction],"\(p.spread)%","",""]};if p.mode==4{return ["",seconds(sampleCursor),"\(p.slices.count) / \(sampleChops)","","","","",""]};return ["",seconds(p.start),seconds(p.end),"\(sampleZoom)x","\(p.octave ?? 0)","","",""]}
    func sampleSoft(_ i:Int){if i==0{samplePreview();return};if page==9{switch i{case 1:applySampleEffect();case 2:tm_preview_stop();history(true);waveCache=nil;case 3...5:sampleFocus=i-3;case 6:sampleEffect=(sampleEffect+sampleEffects.count-1)%sampleEffects.count;sampleFocus=3;case 7:sampleEffect=(sampleEffect+1)%sampleEffects.count;sampleFocus=3;default:break};return};if i==6||i==7{sampleChangeMode(i==6 ? -1:1);return};let p=sampleSettings;if p.mode==4{switch i{case 1,2:sampleFocus=i-1;case 3:sampleAddSlice();case 4:sampleRemoveSlice();case 5:sampleChop(true);default:break}}else if i==4&&p.mode != 5{sampleFocus=7}else if (1...5).contains(i){sampleFocus=i-1}}
