    func waveBox()->NSRect{NSRect(x:35,y:100,width:bounds.width*0.72-55,height:max(140,footerY-128))}
    func waveRange()->(Int,Int){let n=max(1,samplerFrames),width=max(1,n/sampleZoom),p=sampleSettings,center=page==8&&p.mode==5 ? p.start+Int(Double(p.end-p.start)*Double(p.position)/1000):page==8&&p.mode==4 ? sampleCursor:sampleFocus==1 ? p.end:p.start;let lo=max(0,min(n-width,center-width/2));return(lo,min(n,lo+width))}
    func wavePeaks()->[(Float,Float)]{guard let data=samplerSlot.pcm else{return []};if waveCache != data{let p=SampleEditing.floats(data),n=min(2048,p.count);wavePCMCache=p;waveViewStart = -1;wavePeakCache=(0..<n).map{i in let start=i*p.count/n,end=max(start+1,(i+1)*p.count/n);var lo:Float=1,hi:Float = -1;for j in start..<end{let v=p[j].isFinite ? p[j]:0;lo=min(lo,v);hi=max(hi,v)};return(lo,hi)};waveCache=data};return wavePeakCache}
