    func drawSampler(){let w=bounds.width,b=waveBox(),p=sampleSettings;rect(27,54,w-54,30,gray(0.77));txt(page==9 ? "SAMPLE EDITOR":"SAMPLE PLAYBACK",39,63,12,.black,true);txt(String(format:"%02d",instrumentRow+1)+"  "+String(samplerSlot.name.prefix(45)),w*0.58,63,12,.black,true);rect(b.minX,b.minY,b.width,b.height,gray(0.08));border(b.minX,b.minY,b.width,b.height,gray(0.3));guard samplerFrames>0 else{centered("No audio in this instrument — 8 Sample Loader",b.minX,b.midY,b.width,12,gray(0.7));return};let (lo,hi)=waveRange(),span=max(1,hi-lo);func xPos(_ frame:Int)->CGFloat{b.minX+b.width*CGFloat(frame-lo)/CGFloat(span)};let left=max(b.minX,xPos(p.start)),right=min(b.maxX,xPos(p.end));if right>left{rect(left,b.minY,right-left,b.height,gray(0.14))};let mid=b.midY,path=NSBezierPath(),columns=max(1,min(1000,Int(b.width))),peaks=wavePeaksForRange(lo,hi,columns);for c in 0..<columns{let (l,h)=peaks[c],x=b.minX+CGFloat(c)*b.width/CGFloat(columns),amp=b.height*0.43;path.move(to:NSPoint(x:x,y:mid-CGFloat(h)*amp));path.line(to:NSPoint(x:x,y:mid-CGFloat(l)*amp))};gray(0.83).setStroke();path.lineWidth=1;path.stroke();rect(b.minX,mid,b.width,1,gray(0.35));for (frame,color,label) in [(p.start,recColor,"START"),(p.end,gray(0.8),"END")]{let x=xPos(frame);if x>=b.minX&&x<=b.maxX{rect(x,b.minY,2,b.height,color);txt(label,min(x+4,b.maxX-40),b.minY+7,9,color,true)}}
        if p.mode==4{for (i,frame) in p.slices.enumerated(){let x=xPos(frame);if x>=b.minX&&x<=b.maxX{rect(x,b.minY+22,1,b.height-22,teal);txt("\(i+1)",min(x+3,b.maxX-16),b.minY+26,10,teal,true)}};let x=xPos(sampleCursor);if x>=b.minX&&x<=b.maxX{rect(x,b.minY,2,b.height,recColor)}}else if p.mode==5&&page==8{let a=positionAutomation,position=a.mode==0 ? p.position:Int(tm_sample_position(Int32(instrumentRow))),pos=p.start+Int(Double(p.end-p.start)*Double(position)/1000),x=xPos(pos),grainWidth=b.width*CGFloat(Double(p.grainLength)*samplerRate/1000)/CGFloat(span);rect(max(b.minX,x),b.minY,max(0,min(b.maxX-x,grainWidth)),b.height,teal.withAlphaComponent(0.12));if x>=b.minX&&x<=b.maxX{rect(x,b.minY,2,b.height,teal)}}
        let sx=b.maxX+14,sw=max(140,w-sx-30);rect(sx,b.minY,sw,b.height,gray(0.15));let list=page==9 ? sampleEffects:playbackModes,selected=page==9 ? sampleEffect:p.mode;for (i,item) in list.enumerated(){let y=b.minY+12+CGFloat(i)*34;if i==selected{rect(sx+6,y,sw-12,30,gray(0.29));border(sx+6,y,sw-12,30,gray(0.78))};txt(item,sx+13,y+9,12,i==selected ? teal:terminText,true)};let sy=b.minY+CGFloat(list.count)*34+26;if page==9{if sampleEffect==2{txt("Bits: \(sampleBits)  [B]",sx+10,sy,12,sampleFocus==4 ? teal:terminText);txt("Rate hold: \(sampleHold)x  [C]",sx+10,sy+24,12,sampleFocus==6 ? teal:terminText)}else if sampleEffect==5{txt("Length: \(sampleStretch)%  [B]",sx+10,sy,12,sampleFocus==4 ? teal:terminText);txt("Pitch preserved / R3",sx+10,sy+24,11,gray(0.8));txt(String(format:"%.2fs → %.2fs",Double(p.end-p.start)/samplerRate,Double(p.end-p.start)/samplerRate*Double(sampleStretch)/100),sx+10,sy+44,11,yellow)}else if sampleEffect>=3{txt("Slices: \(sampleChops)  [B]",sx+10,sy,12,sampleFocus==4 ? teal:terminText)}}else if p.mode==4{txt("C1 maps to slice 1",sx+10,sy,12,cyan);txt("Option pads audition slices",sx+10,sy+24,10,gray(0.7))}else if p.mode==5&&page==8{let a=positionAutomation;txt("A / Enter: Position automation",sx+10,sy,11,teal,true);txt(PositionAutomation.modes[a.mode],sx+10,sy+24,11,gray(0.8));if a.mode>0{txt("\(PositionAutomation.shapes[a.shape]) · \(a.speedLabel)",sx+10,sy+44,11,yellow)}};txt(String(format:"Octave: %+d  [O]",p.octave ?? 0),sx+10,b.maxY-55,11,sampleFocus==7 ? teal:gray(0.8),true);txt("I + Q/E : Instrument",sx+10,b.maxY-30,10,sampleFocus==5 ? teal:gray(0.7))
    }
    func sampleMouse(_ point:NSPoint)->Bool{let b=waveBox();if point.x>=b.maxX+14&&point.y>=b.minY+12&&point.y<b.minY+12+CGFloat(page==9 ? sampleEffects.count:playbackModes.count)*34{let i=Int((point.y-b.minY-12)/34);if page==9{sampleEffect=i;sampleFocus=3}else{var p=sampleSettings;p.mode=i;if i==4&&p.slices.count<2{p.slices=SampleEditing.evenly(p.start,p.end,sampleChops)};setSampleSettings(p);sampleFocus=0};needsDisplay=true;return true};if b.contains(point)&&samplerFrames>0{sampleDragging=true;checkpoint();dragSample(point);return true};return false}
